WITH cleaned AS (SELECT *, COALESCE(units, 0) AS units_filled, MONTH(sale_date) AS sale_date_month FROM store_sales WHERE sale_date > TO_DATE('2023-06-11')), with_windows AS (SELECT id, store_id, revenue, units_filled, sale_date_month, ROUND(units / SUM(units) OVER (PARTITION BY store_id), 4) AS units_share, ROW_NUMBER() OVER (ORDER BY revenue DESC, id) AS row_seq, FIRST_VALUE(units_filled) IGNORE NULLS OVER (PARTITION BY store_id ORDER BY sale_date_month, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_units_filled, LAST_VALUE(units_filled, TRUE) OVER (PARTITION BY store_id ORDER BY sale_date_month, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_units_filled, FIRST_VALUE(units, TRUE) OVER (PARTITION BY product_id ORDER BY revenue, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_units FROM cleaned WHERE MONTH(sale_date) IN (2, 6, 7)), cleaned_store_sales AS (SELECT *, units_share * units_filled AS units_share_times_units_filled, row_seq + sale_date_month AS row_seq_plus_sale_date_month FROM with_windows WHERE first_known_units_filled BETWEEN 76 AND 77), with_dims AS (SELECT e.*, s.city, s.opened_date, s.sqft FROM cleaned_store_sales e LEFT JOIN stores s ON e.store_id = s.id), ranked AS (SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY city ORDER BY last_known_units_filled DESC, id) AS row_num FROM with_dims) x WHERE row_num = 1) SELECT dim.region, e.city AS store_sale_city, COUNT(*) AS rows_total, AVG(e.first_known_units) AS avg_first_known_units, AVG(e.first_known_units_filled) AS avg_first_known_units_filled, GROUPING_ID() AS grouping_level FROM ranked e LEFT JOIN stores dim ON e.store_id = dim.id GROUP BY ROLLUP (dim.region, e.city)
